  27	 * the filesystem. The caller decides which paths exist before loading them.
  28	 */
  29	export function buildPiRuntimeResourcePaths(
  30		extensionResourcesDir: string,
  31		agentDir: string,
  32		settings: unknown,
  33	): PiRuntimeResourcePaths {
  34		const enabled = getEnabledBundledResources(settings);
  35		const enabledIds = new Set(enabled.map((resource) => resource.id));
  36		const bundledExtensionPaths = [
  37			["custom-footer", "custom-footer.ts"],
  38			["filechanges", "filechanges.ts"],
  39		]
  40			.filter(([id]) => enabledIds.has(id as "custom-footer" | "filechanges"))
  41			.map(([, filename]) => join(extensionResourcesDir, filename));
  42		const bundledThemePaths = enabledIds.has("nebula-pulse")
  43			? [join(extensionResourcesDir, "..", "themes", "nebula-pulse.json")]
  44			: [];
  45	
  46		return {
  47			bundledExtensionPaths,
  48			bundledThemePaths,
  49			rpivTodoPath: join(
  50				agentDir,
  51				"npm",
  52				"node_modules",
  53				"@juicesharp",
  54				"rpiv-todo",
  55				"index.ts",
  56			),
  57		};
  58	}
