  60	export function buildPiResourceLoaderOptions(
  61		cwd: string,
  62		agentDir: string,
  63		resourcePaths: PiRuntimeResourcePaths,
  64	): PiResourceLoaderOptions {
  65		return {
  66			cwd,
  67			agentDir,
  68			noExtensions: false,
  69			additionalExtensionPaths: [...resourcePaths.bundledExtensionPaths],
  70			additionalThemePaths: [...resourcePaths.bundledThemePaths],
  71		};
  72	}
