  53			kind: "theme",
  54			enabledByDefault: true,
  55		},
  56	];
  57	
  58	export interface BundledResourceConfig {
  59		bundledExtensions: {
  60			"custom-footer": boolean;
  61			filechanges: boolean;
  62		};
  63		bundledThemes: {
  64			"nebula-pulse": boolean;
  65		};
  66	}
  67	
  68	function isRecord(value: unknown): value is Record<string, unknown> {
  69		return typeof value === "object" && value !== null && !Array.isArray(value);
  70	}
  71	
  72	/** Read CodePi's bundled-resource toggles without trusting malformed settings. */
  73	export function readBundledResourceConfig(
  74		settings: unknown,
  75	): BundledResourceConfig {
  76		const defaults: BundledResourceConfig = {
  77			bundledExtensions: { "custom-footer": true, filechanges: true },
  78			bundledThemes: { "nebula-pulse": true },
  79		};
  80		if (!isRecord(settings) || !isRecord(settings.codepi)) return defaults;
  81	
  82		const codepi = settings.codepi;
  83		const extensions = isRecord(codepi.bundledExtensions)
  84			? codepi.bundledExtensions
  85			: undefined;
  86		const themes = isRecord(codepi.bundledThemes)
  87			? codepi.bundledThemes
  88			: undefined;
  89		return {
  90			bundledExtensions: {
  91				"custom-footer":
  92					typeof extensions?.["custom-footer"] === "boolean"
  93						? extensions["custom-footer"]
  94						: defaults.bundledExtensions["custom-footer"],
  95				filechanges:
  96					typeof extensions?.filechanges === "boolean"
  97						? extensions.filechanges
  98						: defaults.bundledExtensions.filechanges,
  99			},
 100			bundledThemes: {
 101				"nebula-pulse":
 102					typeof themes?.["nebula-pulse"] === "boolean"
 103						? themes["nebula-pulse"]
 104						: defaults.bundledThemes["nebula-pulse"],
 105			},
 106		};
 107	}
 108	
 109	/** Return the bundled resources enabled by the current CodePi settings. */
 110	export function getEnabledBundledResources(
 111		settings: unknown,
 112	): BundledResourceMetadata[] {
 113		const config = readBundledResourceConfig(settings);
 114		return BUNDLED_RESOURCES.filter((resource) =>
 115			resource.kind === "extension"
 116				? config.bundledExtensions[resource.id as "custom-footer" | "filechanges"]
 117				: config.bundledThemes["nebula-pulse"],
 118		).map((resource) => ({ ...resource }));
 119	}
